# STEP 17.1g-a: writes src/roads/island/IslandLinkData.ts (island link M6-1: centreline, finished heights, structure range) from
# docs/island_link_align.json (17.1c) + docs/island_link_profile.json (17.1d, deck option A = 6 m clearance, deck 10.0 m).
# Run: python3 tools/island-link-data.py        (do not edit the generated file by hand; change OPTION to use another deck option)
import json
OPTION = 'A'
S_FROM = 24.9   # first station used: the ring pavement edge is 22.1 m from the ring centreline (the S node), so the road starts just outside it (no overlap with the ring ribbon)
a = json.load(open('docs/island_link_align.json')); p = json.load(open('docs/island_link_profile.json'))
o = [q for q in p['options'] if q['id'] == OPTION][0]
sm = a['samples']; ys = o['y']; st = p['stations']
assert len(sm) == len(ys) == len(st) and all(abs(sm[i][0] - st[i][0]) < 0.01 for i in range(len(sm)))
idx = [i for i in range(len(sm)) if sm[i][0] >= S_FROM - 1e-6]
s = [round(sm[i][0], 1) for i in idx]
pts = [[round(sm[i][1], 2), round(sm[i][2], 2)] for i in idx]
y = [round(ys[i], 3) for i in idx]
structs = [[round(r['a'], 1), round(r['b'], 1)] for r in o['structRuns']]
out = ['// GENERATED by tools/island-link-data.py (STEP 17.1g-a). Do not edit: rerun the tool. Island link M6-1: centreline (17.1c, ONE PI, R 1000), finished surface heights',
       '// (17.1d, deck option %s: %s), and the structure range (mainland viaduct + strait bridge + island viaduct). Station s = metres from the ring S node (st 1205 of the ring), points about every 5 m, first point s %.1f (just outside the ring pavement).' % (OPTION, o['name'], s[0]),
       'export interface IslandLinkData { name: string; option: string; s: number[]; pts: number[][]; ys: number[]; structs: number[][] }',
       'export const ISLAND_LINK_DATA: IslandLinkData = { name: \'M6-1\', option: %s, s: %s, pts: %s, ys: %s, structs: %s };' % (json.dumps(OPTION), json.dumps(s), json.dumps(pts), json.dumps(y), json.dumps(structs))]
open('src/roads/island/IslandLinkData.ts', 'w', newline='').write('\n'.join(out) + '\n')
print('written', len(s), 'points, s', s[0], '..', s[-1], 'structs', structs)
